import sys
import json

def _loads_obj(raw):
    if not raw:
        return {}
    try:
        data = json.loads(raw)
        return data if isinstance(data, dict) else {}
    except (TypeError, json.JSONDecodeError):
        return {}

def _status(raw):
    try:
        if raw is None or raw == "":
            return None
        return int(raw)
    except (TypeError, ValueError):
        return None

curr_table = json.loads(sys.argv[1]) if sys.argv[1] else []
if not isinstance(curr_table, list):
    curr_table = []

org_id = sys.argv[2] or ""
org_name = sys.argv[3] or ""
api_raw = sys.argv[4] or ""
saml_body = _loads_obj(sys.argv[5])
login_body = _loads_obj(sys.argv[6])
saml_code = _status(sys.argv[7])
login_code = _status(sys.argv[8])
saml_parallel_err = (sys.argv[9] or "").strip()
login_parallel_err = (sys.argv[10] or "").strip()

api_obj = _loads_obj(api_raw)
if not api_obj and api_raw.strip().lower() in ("true", "false"):
    api_obj = {"enabled": api_raw.strip().lower() == "true"}

saml_ok = saml_code == 200
login_ok = login_code == 200
if saml_ok and login_ok:
    outcome = "complete"
elif saml_ok or login_ok:
    outcome = "partial"
else:
    outcome = "failed"

entry = {
    "orgId": org_id,
    "orgName": org_name,
    "outcome": outcome,
    "samlStatusCode": saml_code,
    "loginSecurityStatusCode": login_code,
}

if api_obj:
    if "enabled" in api_obj:
        entry["apiEnabled"] = api_obj.get("enabled")

if saml_ok:
    if "enabled" in saml_body:
        entry["samlEnabled"] = saml_body.get("enabled")
else:
    entry["samlError"] = saml_parallel_err or "SAML settings request failed."

if login_ok:
    for key in (
        "enforcePasswordExpiration",
        "passwordExpirationDays",
        "enforceDifferentPasswords",
        "numDifferentPasswords",
        "enforceStrongPasswords",
        "minimumPasswordLength",
        "enforceAccountLockout",
        "accountLockoutAttempts",
        "enforceIdleTimeout",
        "idleTimeoutMinutes",
        "enforceTwoFactorAuth",
        "enforceLoginIpRanges",
        "loginIpRanges",
        "apiAuthentication",
    ):
        if key in login_body and login_body.get(key) is not None:
            entry[key] = login_body.get(key)
else:
    entry["loginSecurityError"] = login_parallel_err or "Login security settings request failed."

curr_table.append(entry)
result = json.dumps(curr_table)
